INSERT INTO `page_list` (`alias`, `page_title`, `page_content`, `status`) VALUES
('glowna', 'Strona główna', '<section id=\"demo-lab3\">\r\n    <button type=\"button\" class=\"anim-btn\" id=\"btn-anim-a\" aria-pressed=\"false\">Animacja A</button>\r\n    <button type=\"button\" class=\"anim-btn\" id=\"btn-anim-b\">Animacja B</button>\r\n    <button type=\"button\" class=\"anim-btn\" id=\"btn-anim-c\">Animacja C</button>\r\n    <p id=\"status-c\">Liczba kroków: 0</p>\r\n    <button type=\"button\" id=\"btn-reset\">Resetuj A i C</button>\r\n</section>\r\n<section id=\"demo-ajax\">\r\n    <button type=\"button\" id=\"btn-check-server\">Sprawdź serwer</button>\r\n    <output id=\"ajax-status\" role=\"status\">Oczekiwanie na sprawdzenie...</output>\r\n</section>\r\n<section id=\"search-section\">\r\n    <label for=\"search-input\">Szukaj produktu:</label>\r\n    <input type=\"search\" id=\"search-input\" placeholder=\"Wpisz nazwę...\">\r\n    <section aria-live=\"polite\" id=\"search-status\">\r\n        <p id=\"search-counter\"></p>\r\n        <p id=\"no-results\" hidden>Brak produktów spełniających kryteria wyszukiwania.</p>\r\n    </section>\r\n</section>\r\n<article class=\"card\">\r\n    <a href=\"index.php?idp=produkt\" class=\"card-link\">\r\n    <h2>TCG Riftbound: Radiance - Booster Box</h2>\r\n    <img src=\"img/booster_box.png\" alt=\"Booster box kart z Riftbound: Radiance\" width=\"300\" height=\"300\">\r\n    <p>Booster box z Riftbound: Radiance. Zawiera 24 boosterów po 14 kart.</p>\r\n    <h3>Cena: 650 zł</h3>\r\n    </a>\r\n</article>\r\n<article class=\"card\">\r\n    <h2>TCG Riftbound: Wendeta - Talia Zed vs Shen</h2>\r\n    <img src=\"img/showdown_deck.png\" alt=\"Zestaw dwóch talii kart z bohaterami Zed i Shen\" width=\"300\" height=\"300\">\r\n    <p>Zawiera dwie gotowe talie do gry Riftbound, w których role główne odgrywają Zed i Shen.</p>\r\n    <h3>Cena: 160 zł</h3>\r\n</article>\r\n<article class=\"card\">\r\n    <h2>TCG Riftbound: Origins - Talia Jinx</h2>\r\n    <img src=\"img/talia_jinx.png\" alt=\"Talia kart bohaterki Jinx do gry Riftbound\" width=\"300\" height=\"300\">\r\n    <p>Zawiera gotową talię kart bohaterki Jinx do gry Riftbound.</p>\r\n    <h3>Cena: 100 zł</h3>\r\n</article>', 1),
('produkt', 'Produkt', '<h2>TCG Riftbound: Radiance - Booster Box</h2>\r\n<img class=\"product-image\" src=\"img/booster_box.png\" alt=\"Booster box kart z Riftbound: Radiance\" width=\"300\" height=\"300\">\r\n<h3>Cena: 650 zł</h3>\r\n<a class=\"product-link\" href=\"index.php?idp=kontakt\">Zapytaj o produkt</a>\r\n<p>Opis produktu: <strong>Booster Box Radiance</strong> to opakowanie zbiorcze z piątego, głównego dodatku do kolekcjonerskiej gry karcianej <em>Riftbound: League of Legends TCG</em> od <em>Riot Games</em>. Dodatek ten skupia się na zaciętej rywalizacji, poszerzając grę o nowe mechaniki i przenosząc w centrum uwagi kolejnych znanych bohaterów z Runeterry.</p>\r\n<ul>\r\n    <li>Zawiera 24 boosterów po 14 kart.</li>\r\n    <li>Średnio w każdym pudełku pojawia się ponad 6 epickich kart i ponad 2 specjalne karty z alternatywną grafiką.</li>\r\n    <li>Zawiera oryginalne grafiki autorstwa jednych z najbardziej znanych artystów w historii League of Legends.</li>\r\n</ul>\r\n<table>\r\n    <caption>Specyfikacja produktu</caption>\r\n    <thead>\r\n        <tr>\r\n        <th scope=\"col\">Liczba boosterów</th>\r\n        <th scope=\"col\">Język</th>\r\n        <th scope=\"col\">Licencja</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            <td>24</td>\r\n            <td>Angielski</td>\r\n            <td>Riot Games</td>\r\n        </tr>\r\n    </tbody>\r\n</table>', 1),
('kontakt', 'Kontakt', '<form id=\"contact-form\" method=\"get\" action=\"kontakt.html\">\r\n    <p><em>Podgląd lokalny. Formularz nie wysyła wiadomości.</em></p>\r\n\r\n    <label for=\"email\">E-mail (wymagane): </label>\r\n    <input id=\"email\" type=\"email\" name=\"email\" required>\r\n\r\n    <label for=\"produkt\">Produkt (wymagane): </label>\r\n    <select id=\"produkt\" name=\"produkt\" required>\r\n        <option value=\"\">Wybierz produkt</option>\r\n        <option value=\"booster_box\">Booster Box Riftbound: Radiance</option>\r\n        <option value=\"showdown_deck\">Talia Zed vs Shen</option>\r\n        <option value=\"talia_jinx\">Talia Jinx</option>\r\n    </select>\r\n\r\n    <label for=\"ilosc\">Liczba sztuk (wymagane, od 1 do 5): </label>\r\n    <input id=\"ilosc\" type=\"number\" name=\"ilosc\" min=\"1\" max=\"5\" step=\"1\" required>\r\n\r\n    <p id=\"value\"></p>\r\n\r\n    <label for=\"wiadomosc\">Wiadomość (wymagane, 10-500 znaków): </label>\r\n    <textarea id=\"wiadomosc\" name=\"wiadomosc\" minlength=\"10\" maxlength=\"500\" required></textarea>\r\n\r\n    <p id=\"msg-error\" hidden>Wiadomość musi mieć minimum 10 znaków.</p>\r\n\r\n    <button type=\"submit\">Sprawdź zapytanie</button>\r\n</form>\r\n<section id=\"summary\" hidden>\r\n    <p>Produkt: <output id=\"sum-prod\"></output></p>\r\n    <p>Ilość: <output id=\"sum-ilosc\"></output></p>\r\n    <p>Wartość: <output id=\"sum-wart\"></output></p>\r\n    <p>Wiadomość: <output id=\"sum-msg\"></output></p>\r\n</section>', 1),
('filmy', 'Filmy', '<article class=\"card video-card\">\r\n    <h3>Prezentacja kart Riftbound: Radiance</h3>\r\n    <div class=\"video-layout\">\r\n        <div class=\"video-container\">\r\n            <iframe\r\n                class=\"video-frame\"\r\n                src=\"https://www.youtube.com/embed/c3CqvmA2uuA?si=oE2sWMnAMQTz8VJ3;rel=0\"\r\n                title=\"Odtwarzacz wideo YouTube: Zwiastun dodatku Riftbound: Radiance\"\r\n                allow=\"accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\"\r\n                referrerpolicy=\"strict-origin-when-cross-origin\"\r\n                allowfullscreen>\r\n            </iframe>\r\n        </div>\r\n        <div class=\"video-details\">\r\n            <p>Prezentacja nowych kart z dodatku Radiance.</p>\r\n            <a class=\"video-link\" href=\"https://youtu.be/c3CqvmA2uuA?si=TTLJX2yjKO54R0Fj\" target=\"_blank\" rel=\"noopener noreferrer\">\r\n                Otwórz film na YouTube\r\n            </a>\r\n        </div>\r\n    </div>\r\n</article>\r\n\r\n<article class=\"card video-card\">\r\n    <h3>Limitowane karty Riftbound x K/DA</h3>\r\n    <div class=\"video-layout\">\r\n        <div class=\"video-container\">\r\n            <iframe\r\n                class=\"video-frame\"\r\n                src=\"https://www.youtube.com/embed/n-53EjaNrdU?si=-YQCdarw_QsW0VLc;rel=0\"\r\n                title=\"Odtwarzacz wideo YouTube: Poradnik rozgrywki — Talia Zed vs Shen\"\r\n                allow=\"accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\"\r\n                referrerpolicy=\"strict-origin-when-cross-origin\"\r\n                allowfullscreen>\r\n            </iframe>\r\n        </div>\r\n        <div class=\"video-details\">\r\n            <p>Prezentacja limitowanych kart z Riftbound x K/DA</p>\r\n            <a class=\"video-link\" href=\"https://youtu.be/n-53EjaNrdU?si=CNy11I3eR2W9yhNN\" target=\"_blank\" rel=\"noopener noreferrer\">\r\n                Otwórz film na YouTube\r\n            </a>\r\n        </div>\r\n    </div>\r\n</article>\r\n\r\n<article class=\"card video-card\">\r\n    <h3>Riftbound - zasady gry</h3>\r\n    <div class=\"video-layout\">\r\n        <div class=\"video-container\">\r\n            <iframe\r\n                class=\"video-frame\"\r\n                src=\"https://www.youtube.com/embed/UCa4PBoj5ss?si=Ni3uwWNabGysKCst;rel=0\"\r\n                title=\"Odtwarzacz wideo YouTube: Prezentacja talii startowej Riftbound Origins — Jinx\"\r\n                allow=\"accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\"\r\n                referrerpolicy=\"strict-origin-when-cross-origin\"\r\n                allowfullscreen>\r\n            </iframe>\r\n        </div>\r\n        <div class=\"video-details\">\r\n            <p>Omówienie wszystkich zasad gry karcianej Riftbound.</p>\r\n            <a class=\"video-link\" href=\"https://youtu.be/UCa4PBoj5ss?si=FAjh5jnHqlLbKqlY\" target=\"_blank\" rel=\"noopener noreferrer\">\r\n                Otwórz film na YouTube\r\n            </a>\r\n        </div>\r\n    </div>\r\n</article>', 1),
('zapowiedzi', 'Zapowiedzi (szkic)', '<article class=\"card\">\r\n    <h2>Zapowiedzi na rok 2027</h2>\r\n    <p>Strona robocza w przygotowaniu.</p>\r\n</article>', 0);